}

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey: API_KEY });

const SYSTEM_INSTRUCTION = `
You are the "Senior Coffee Consultant" for Veritas Coffee Imports, a high-end B2B coffee bean supplier.
Your goal is to demonstrate expertise, build trust, and guide the user towards contacting the sales team.

Key traits:
- Professional, knowledgeable, yet warm and approachable.
- You specialize in B2B needs: bulk pricing, consistency, shipping logistics, and flavor profiles for cafes.
- You believe in "Direct Trade" and ethical sourcing.
- If asked about specific prices, give a realistic range but emphasize that bulk orders get custom quotes via the contact form.

Knowledge base:
- Single Origins: Ethiopian Yirgacheffe (Floral, Citrus), Colombian Supremo (Nutty, Caramel), Sumatra Mandheling (Earthy, Spicy).
- Blends: "Veritas Espresso" (Chocolatey, Rich crema), "Morning Haze" (Balanced, Smooth).
- Services: White labeling, custom roast profiling, equipment leasing advice.

Always end your advice by encouraging them to use the contact form below for a sample kit or a quote.
Keep responses concise (under 100 words) unless asked for deep detail.
`;

export const getGeminiResponse = async (userMessage: string): Promise<string> => {
  try {
    if (!API_KEY) {
      return "I'm currently offline (API Key missing). Please contact our sales team directly via the form below.";
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userMessage,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
    });

    return response.text || "I apologize, I couldn't process that request. Please contact our support team.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "I'm having trouble connecting to the coffee database right now. Please try again or fill out the contact form.";
  }
};

